import{_ as r,a0 as p,w as l,s as i,ao as g,I as a,x as e,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"命令行星期二 ——  第一篇 | LCTT x X-CMD","titleTemplate":false,"description":"命令行星期二 ——  第一篇 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行星期二 ——  第一篇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行星期二 ——  第一篇 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140612 Command Line Tuesdays--Part One","title":"命令行星期二 ——  第一篇","tag":"201406","desc":""},"relativePath":"201406/20140612 Command Line Tuesdays--Part One.md","filePath":"[post].md"}'),m={name:"201406/20140612 Command Line Tuesdays--Part One.md"};function d(u,t,h,f,T,x){const s=p("Link");return l(),i("div",null,[t[11]||(t[11]=g('<h1 id="命令行星期二-——-第一篇" tabindex="-1">命令行星期二 —— 第一篇 <a class="header-anchor" href="#命令行星期二-——-第一篇" aria-label="Permalink to “命令行星期二 ——  第一篇”">​</a></h1><p>极客们，我们又回来了！真抱歉让你们久等了，但我保证，我们又回归正轨了。我们满怀热情与大家相约，让我们激情燃烧，寻找刺激吧:)</p><p>现在，整个的想法已经在之前的开场白中告诉你们了，所以现在让我们来干点正事吧。就像肖茨先生书里讲得那样，我们需要来了解一下shell是个什么东西，终端模拟器又是个什么东西，因为我们要在这里头干活。</p><p>肖茨在他的书中写道，shell实际上是当我们谈论命令行时所谈论的东西。shell基本上一个程序，它将你敲击键盘的动作传递给计算机；它也是某种形式的翻译器，将你所讲的东西翻译给计算机听。在这世界上活着的shell真是五花八门，但是活得最好的要数<strong>bash</strong>了，它在GNU/Linux中随处可见。我们也叫它Bourne Again Shell，这是一个精巧的双关语，因为自从Bourne先生创造了它的祖先<strong>sh</strong>后，Brian Fox又把它重写成为一个自由的sh替代品。啊哈！GUN人和他们的幽默，真的很精明。😃</p><p><img src="http://paste.opensuse.org/images/54535272.jpg" alt=""></p><p>接下来我所需要，是一个让我们能和shell交互的东西，它就是终端模拟器。每个Linux发行版都自带了一个，至于长什么样就得看你使用的桌面环境了，可能是KDE的<strong>Konsole</strong>，也可能是Gnome的<strong>Gnome terminal</strong>等等。肖茨先生说了，你可以挖掘出你所偏爱的一个，但是大部分时间我还是用桌面环境给我提供的那个吧。</p><p>现在来发动你的终端。打开后，你会见到一行字，这行字告诉你用户名和机器的主机名，它叫作shell提示符。它告诉你它准备好了，你可以输入命令了。让我们来随便玩玩，随便输入点什么东西进去，然后敲回车看看。</p><p>呵呵，还记开篇我们讲过，我们需要像学诗歌一样来学习命令吗？记得就好，随意乱来可干不了啥事。</p><p>现在，按那个上箭头，你会发现命令又回来了。这是啥魔法？你键盘上的上箭头用来取出历史命令。终端会保存总计500个你输入过的命令，所以别一次又一次地重复敲它们了，你可以用上/下箭头来查找它们。左右箭头用来在指定行中移动光标，这样你就可以在文本中编辑或者插入了。另外注意，想用<strong>ctrl+v</strong>来粘贴文本是不行的。你可以在某个地方将它设置成快捷键，但是它常常不是那么回事。检查你的模拟器的快捷键！（在Konsole中，它位于设置 &gt; 配置快捷键）</p><p>现在，为了我们不再被‘命令找不到’抽一巴掌，让我们试试一些简单的。敲个<strong>date</strong>来试试。（是的，我不知道有这么个命令，这真着实让我兴奋了一把）😃</p><p><img src="http://paste.opensuse.org/images/7123365.png" alt=""></p><p>你又来了。当你能打开终端并输入date命令来查看日期时，为什么在时钟中看看内建日历会让你不胜其烦 😃 只是开个玩笑。就像肖茨书里写的那样，它确实是个简单的命令，更有用也更复杂的命令会在以后介绍。跟date相关的命令是cal - 它会显示当前月的日历。</p><p>你也可以试试<strong>df</strong>，它会列出你驱动器上的空闲空间。</p><p><img src="http://paste.opensuse.org/images/44662534.png" alt=""></p><p>或者试试<strong>free</strong>来显示空闲内存：</p><p><img src="http://paste.opensuse.org/images/44548116.png" alt=""></p><p>如果你已经跟上了敲击键盘的节奏，你可以输入<strong>exit</strong>命令来关闭终端模拟器了，而不是去点击那个x了。</p><p>嗯，本周我们就到此为止吧，免得有太多的要学的东西来占据你紧巴巴的日程了。下面来个小结（你可以把结论写下来，做个备份吧），在这一篇中，我们学习了：</p><ul><li>什么是shell</li><li>我们需要用什么来和shell交流（终端模拟器）</li><li>使用光标按钮来驾驭终端命令以及退出终端</li></ul><p>四个简单的命令：</p><ul><li><strong>date</strong> – 显示当前日期</li><li><strong>cal</strong> – 显示当前月份的日历</li><li><strong>df</strong> – shows the amount of free space on your hard drives</li><li><strong>free</strong> – amount of free memory</li></ul><h3 id="下周二我们将会做什么呢" tabindex="-1">下周二我们将会做什么呢？ <a class="header-anchor" href="#下周二我们将会做什么呢" aria-label="Permalink to “下周二我们将会做什么呢？”">​</a></h3><p>我们会学习在文件系统中导航（bin、etc等等这所有的文件夹都是些什么东西？它们用来干什么？怎样通过终端来浏览它们）。到那时……</p><h3 id="你就有得乐了" tabindex="-1">你就有得乐了！ <a class="header-anchor" href="#你就有得乐了" aria-label="Permalink to “你就有得乐了！”">​</a></h3><p><img src="http://paste.opensuse.org/images/40949666.jpg" alt=""></p><hr>',26)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),n(s,{href:"https://news.opensuse.org/2014/06/10/command-line-tuesdays-part-one/"},{default:o(()=>[...t[0]||(t[0]=[e("https://news.opensuse.org/2014/06/10/command-line-tuesdays-part-one/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),n(s,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[2]||(t[2]=[e("GOLinux",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(s,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const _=r(m,[["render",d]]);export{P as __pageData,_ as default};
